-- Phase 6 read-only delivery and projection reconciliation.
SELECT count(*) FILTER(WHERE processed_at IS NULL) AS pending_events,count(*) FILTER(WHERE processed_at IS NULL AND attempts>0) AS retrying_events,max(now()-occurred_at) FILTER(WHERE processed_at IS NULL) AS oldest_pending FROM public.integration_outbox;
SELECT event_type,count(*) AS pending,max(attempts) AS max_attempts FROM public.integration_outbox WHERE processed_at IS NULL GROUP BY event_type ORDER BY pending DESC;
SELECT count(*) AS unreplayed_dead_letters FROM public.integration_dead_letters WHERE replayed_at IS NULL;
SELECT outbox_id,consumer_name,count(*) FILTER(WHERE status IN ('succeeded','deduplicated')) AS successful_deliveries FROM public.integration_delivery_attempts GROUP BY outbox_id,consumer_name HAVING count(*) FILTER(WHERE status IN ('succeeded','deduplicated'))>1;
SELECT c.id AS case_id,c.row_version,client.source_version AS client_version,finance.source_version AS finance_version,solicitor.source_version AS solicitor_version,command.source_version AS command_version FROM public.transaction_cases c LEFT JOIN public.client_case_read_model client ON client.case_id=c.id LEFT JOIN public.finance_case_read_model finance ON finance.case_id=c.id LEFT JOIN public.solicitor_case_read_model solicitor ON solicitor.case_id=c.id LEFT JOIN public.command_case_health_read_model command ON command.case_id=c.id WHERE client.case_id IS NULL OR finance.case_id IS NULL OR solicitor.case_id IS NULL OR command.case_id IS NULL OR LEAST(client.source_version,finance.source_version,solicitor.source_version,command.source_version)<c.row_version;
SELECT legal_matter_id,verified,checked,broken_at,failure_reason,verified_at FROM public.legal_audit_verification_runs WHERE verified=false ORDER BY verified_at DESC;
